    image_patch = ImagePatch(image)
    bears = image_patch.find("bear")
    towels = image_patch.find("towel")

    if not bears or not towels:
        return image_patch

    bear_with_towel = [b for b in bears for t in towels if b.overlaps_with(t.left, t.lower, t.right, t.upper)]

    if not bear_with_towel:
        return image_patch

    pink_towels = [t for t in towels if t.verify_property("towel", "pink")]

    if not pink_towels:
        return image_patch

    pink_towel_bear = [b for b in bear_with_towel for t in pink_towels if b.overlaps_with(t.left, t.lower, t.right, t.upper)]

    if not pink_towel_bear:
        return image_patch

    next_to_pink_towel_bear = [b for b in bear_with_towel if b != pink_towel_bear[0] and b.overlaps_with(pink_towel_bear[0].left, pink_towel_bear[0].lower, pink_towel_bear[0].right, pink_towel_bear[0].upper)]

    if not next_to_pink_towel_bear:
        return image_patch

    return next_to_pink_towel_bear[0]

